using System.Collections.Generic; using System.Linq; using NUnit.Framework; using SuijinMaterials.Merchants;
namespace SuijinMaterials.Tests { [TestFixture] public sealed class MerchantStockInstallerTests { [Test] public void Refresh_is_idempotent_and_missing_trader_isolated(){var f=new Fake();f.Missing.Add("Hildir");var i=new MerchantStockInstaller(f,_=>{});var s=i.Install(Default());Assert.Multiple(()=>{Assert.That(s.InstalledCount,Is.EqualTo(2));Assert.That(s.FailedCount,Is.EqualTo(1));Assert.That(f.Active.Count,Is.EqualTo(2));});i.Install(Default());Assert.That(f.Active.Count,Is.EqualTo(2));i.Uninstall();Assert.That(f.Active,Is.Empty);} private static MerchantStockSettings Default()=>new MerchantStockSettings(MerchantStockCatalog.All.ToDictionary(x=>x.ListingId,x=>new MerchantListingSettings(true,x.Price,x.Stack))); private sealed class Fake:IMerchantStockFacade {public readonly HashSet<string> Missing=new HashSet<string>();public readonly List<object> Active=new List<object>();public object Add(MerchantStockDefinition d,MerchantListingSettings s){if(Missing.Contains(d.TraderPrefabId))throw new System.InvalidOperationException();var h=new object();Active.Add(h);return h;}public void Remove(object h){Active.Remove(h);} } } }
